/// `attemptScript` in `internal/ratelimit/attempts.go`.
pub const RATELIMIT_ATTEMPT: &str = "\nlocal key = KEYS[1]\nlocal max = tonumber(ARGV[1])\nlocal window = tonumber(ARGV[2])\nlocal count = tonumber(redis.call('GET', key) or \"0\")\nif count >= max then\n    local ttl = redis.call('PTTL', key)\n    if ttl < 0 then\n        redis.call('PEXPIRE', key, window)\n        ttl = window\n    end\n    return {0, ttl}\nend\ncount = redis.call('INCR', key)\nif count == 1 or count >= max then\n    redis.call('PEXPIRE', key, window)\nend\nreturn {1, 0}\n";

/// `quotaScript` in `internal/ratelimit/session_quota.go`.
pub const RATELIMIT_QUOTA: &str = "\nlocal rate = tonumber(ARGV[1])\nlocal burst = tonumber(ARGV[2])\nlocal t = redis.call('TIME')\nlocal now = tonumber(t[1]) + tonumber(t[2]) / 1000000\nlocal stored = redis.call('HMGET', KEYS[1], 'tokens', 'updated')\nlocal tokens = tonumber(stored[1])\nlocal updated = tonumber(stored[2])\nif tokens == nil or updated == nil then\n    tokens = burst\n    updated = now\nend\nif now > updated then\n    tokens = math.min(burst, tokens + (now - updated) * rate)\n    updated = now\nend\nlocal allowed = 0\nif tokens >= 1 then\n    tokens = tokens - 1\n    allowed = 1\nend\nredis.call('HSET', KEYS[1], 'tokens', tostring(tokens), 'updated', tostring(updated))\nlocal missing = math.min(1, math.max(0, 1 - tokens / burst))\nredis.call('EXPIRE', KEYS[1], math.max(1, math.ceil(missing * tonumber(ARGV[3]))))\nreturn {allowed, tostring(tokens)}\n";

/// `rateLimitScript` in `internal/ratelimit/redis.go`.
pub const RATELIMIT_WINDOW: &str = "\nlocal sec_key = KEYS[1]\nlocal min_key = KEYS[2]\nlocal sec_limit = tonumber(ARGV[1])\nlocal min_limit = tonumber(ARGV[2])\n\n-- Check current counts before incrementing\nlocal sec_count = tonumber(redis.call('GET', sec_key) or \"0\")\nlocal min_count = tonumber(redis.call('GET', min_key) or \"0\")\n\n-- Deny if either limit is exceeded\nif sec_count >= sec_limit then\n    local sec_ttl = redis.call('TTL', sec_key)\n    if sec_ttl < 0 then sec_ttl = 1 end\n    return {0, sec_count, sec_limit, min_count, min_limit, sec_ttl}\nend\nif min_count >= min_limit then\n    local sec_ttl = redis.call('TTL', sec_key)\n    if sec_ttl < 0 then sec_ttl = 1 end\n    return {0, sec_count, sec_limit, min_count, min_limit, sec_ttl}\nend\n\n-- Allowed: increment both counters\nsec_count = redis.call('INCR', sec_key)\nif sec_count == 1 then\n    redis.call('EXPIRE', sec_key, 2)\nend\n\nmin_count = redis.call('INCR', min_key)\nif min_count == 1 then\n    redis.call('EXPIRE', min_key, 120)\nend\n\nlocal sec_ttl = redis.call('TTL', sec_key)\nreturn {1, sec_count, sec_limit, min_count, min_limit, sec_ttl}\n";

/// `putNodeRecipeScript` in `internal/noderecipe/store.go`.
pub const NODERECIPE_PUT: &str = "\nlocal generation = redis.call(\"GET\", KEYS[3])\nif not generation then\n  generation = \"0\"\nend\nredis.call(\"SET\", KEYS[1], ARGV[1], \"PX\", ARGV[2])\nredis.call(\"SET\", KEYS[2], generation, \"PX\", ARGV[2])\nredis.call(\"SET\", KEYS[4], ARGV[3], \"PX\", ARGV[2])\nreturn generation\n";

/// `validateLegacyNodeRecipeScript` in `internal/noderecipe/store.go`.
pub const NODERECIPE_VALIDATE_LEGACY: &str = "\nlocal recipe = redis.call(\"GET\", KEYS[1])\nif not recipe or recipe ~= ARGV[1] then\n  return 0\nend\nlocal binding = redis.call(\"GET\", KEYS[4])\nif binding and binding == ARGV[3] then\n  local stamped_generation = tonumber(redis.call(\"GET\", KEYS[2]))\n  local current_generation = tonumber(redis.call(\"GET\", KEYS[3])) or 0\n  if stamped_generation and stamped_generation == current_generation then\n    return 1\n  end\n  return 0\nend\nlocal generation = tonumber(redis.call(\"GET\", KEYS[3]))\nif not generation or generation == 0 then\n  return 1\nend\nlocal ttl = redis.call(\"PTTL\", KEYS[1])\nif ttl < 0 then\n  return 0\nend\nlocal now = redis.call(\"TIME\")\nlocal now_ms = now[1] * 1000 + math.floor(now[2] / 1000)\nlocal issued_at = now_ms - (tonumber(ARGV[2]) - ttl)\nif issued_at > generation then\n  return 1\nend\nreturn 0\n";

/// `revokeNodeScript` in `internal/noderecipe/store.go`.
pub const NODERECIPE_REVOKE_NODE: &str = "\nlocal now = redis.call(\"TIME\")\nlocal now_ms = now[1] * 1000 + math.floor(now[2] / 1000)\nlocal current = tonumber(redis.call(\"GET\", KEYS[1])) or 0\nif now_ms <= current then\n  now_ms = current + 1\nend\nredis.call(\"SET\", KEYS[1], now_ms)\nreturn now_ms\n";

/// `sharedBandwidthScript` in `internal/downloads/bandwidth.go`.
pub const DOWNLOADS_SHARED_BANDWIDTH: &str = "\nlocal clock = redis.call('TIME')\nlocal now = tonumber(clock[1]) + tonumber(clock[2]) / 1000000\nlocal n = tonumber(ARGV[3])\nlocal delay = 0\nfor i = 1,2 do\n local rate = tonumber(ARGV[i])\n if rate > 0 then\n  local burst = math.max(rate / 4, 32768)\n  local state = redis.call('HMGET', KEYS[i], 'tokens', 'time', 'rate')\n  local tokens = burst\n  if state[1] then\n   tokens = math.min(burst, tonumber(state[1]) + math.max(0, now - tonumber(state[2])) * tonumber(state[3]))\n  end\n  tokens = tokens - n\n  local wait = math.max(0, -tokens) / rate\n  delay = math.max(delay, wait)\n  redis.call('HSET', KEYS[i], 'tokens', tokens, 'time', now, 'rate', rate)\n  redis.call('EXPIRE', KEYS[i], 60 + math.ceil(wait))\n end\nend\nreturn math.ceil(delay * 1000000)\n";

/// `script` in `internal/catalog/search_session.go`.
pub const CATALOG_SEARCH_SESSION_PUT: &str = "\nredis.call('SET', KEYS[1], ARGV[1], 'PX', ARGV[2])\nredis.call('ZREMRANGEBYSCORE', KEYS[2], '-inf', ARGV[3])\nlocal excess = redis.call('ZCARD', KEYS[2]) - tonumber(ARGV[5]) + 1\nif excess > 0 then\n local old = redis.call('ZPOPMIN', KEYS[2], excess)\n for i=1,#old,2 do redis.call('DEL', old[i]) end\nend\nredis.call('ZADD', KEYS[2], ARGV[4], KEYS[1])\nredis.call('PEXPIRE', KEYS[2], ARGV[2])\nreturn 1";
